// Compact SynthID carrier codebook distilled offline from the reverse-SynthID
// V4 spectral codebook (https://github.com/aloshdenny/reverse-SynthID, MIT
// License). Generated, not maintained by hand. If the upstream carrier set
// changes, regenerate with the upstream project's tooling (Python + numpy),
// which reads its own LZMA-compressed .npz archive that browser tooling does
// not decode.
// Each channel string is base64 of packed 7-byte records: uint16 y, uint16 x,
// uint8 consensus (0-255), int16 phase in milliradians, sorted by consensus
// descending.
export interface SynthidCodebookProfile {
	model: string;
	h: number;
	w: number;
	channels: string[];
}

export interface SynthidCodebook {
	format: string;
	source: string;
	consensusFloor: number;
	profiles: SynthidCodebookProfile[];
}

